namespace Greyhaven.Content;
// Transactional editor operations are shared with tests; invalid candidates never replace the document.
public sealed class MapWorkshop(ContentPackage package,WorldMap initial) {
 public WorldMap Map {get;private set;}=initial.Clone();readonly Stack<WorldMap> undo=new(),redo=new();public bool Dirty {get;private set;}
 public void Change(Action<WorldMap> edit,bool validate=false){var next=Map.Clone();edit(next);next.InvalidateSpatial();if(validate)package.ValidateMap(next);undo.Push(Map);while(undo.Count>30){var a=undo.Reverse().Skip(1).ToArray();undo.Clear();foreach(var m in a)undo.Push(m);}Map=next;redo.Clear();Dirty=true;}
 public bool Undo(){if(undo.Count==0)return false;redo.Push(Map);Map=undo.Pop();Dirty=true;return true;}
 public bool Redo(){if(redo.Count==0)return false;undo.Push(Map);Map=redo.Pop();Dirty=true;return true;}
 public void Saved()=>Dirty=false;
 public static void Terrain(WorldMap m,int x,int y,int radius,string terrain){for(int yy=y-radius;yy<=y+radius;yy++)for(int xx=x-radius;xx<=x+radius;xx++)if(m.Contains(xx,yy)&&!(xx==m.Spawn.X&&yy==m.Spawn.Y))m.Get(xx,yy).Terrain=terrain;}
 public static void Rectangle(WorldMap m,int x,int y,int tx,int ty,string terrain){for(int yy=Math.Min(y,ty);yy<=Math.Max(y,ty);yy++)for(int xx=Math.Min(x,tx);xx<=Math.Max(x,tx);xx++)if(m.Contains(xx,yy)&&!(xx==m.Spawn.X&&yy==m.Spawn.Y))m.Get(xx,yy).Terrain=terrain;}
 public static void Flood(WorldMap m,int x,int y,string terrain){if(!m.Contains(x,y))return;string source=m.Get(x,y).Terrain;if(source==terrain)return;var q=new Queue<(int x,int y)>();var seen=new HashSet<(int,int)>();q.Enqueue((x,y));while(q.TryDequeue(out var t)){if(!m.Contains(t.x,t.y)||m.Get(t.x,t.y).Terrain!=source||!seen.Add(t))continue;if(t.x!=m.Spawn.X||t.y!=m.Spawn.Y)m.Get(t.x,t.y).Terrain=terrain;foreach(var d in new[]{(1,0),(-1,0),(0,1),(0,-1)})q.Enqueue((t.x+d.Item1,t.y+d.Item2));}}
 public static void Elevation(WorldMap m,int x,int y,int radius,int dz){for(int yy=y-radius;yy<=y+radius;yy++)for(int xx=x-radius;xx<=x+radius;xx++)if(m.Contains(xx,yy)){m.Get(xx,yy).Z=Math.Clamp(m.Get(xx,yy).Z+dz,-32,32);foreach(var o in m.ObjectsAt(xx,yy))o.Z=m.Get(xx,yy).Z;if(xx==m.Spawn.X&&yy==m.Spawn.Y)m.Spawn.Z=m.Get(xx,yy).Z;}}
 public static void Prefab(WorldMap m,int x,int y,string type){int w=type=="inn"?12:8,h=type=="inn"?10:8;if(!m.Contains(x,y)||!m.Contains(x+w-1,y+h))throw new ContentException("Prefab would leave the map.");if(m.Roofs.Any(r=>x<r.X+r.Width&&x+w>r.X&&y<r.Y+r.Height&&y+h>r.Y))throw new ContentException("Prefab overlaps an existing roof group.");if(m.Objects.Any(o=>o.X>=x&&o.X<x+w&&o.Y>=y&&o.Y<y+h)||m.Spawn.X>=x&&m.Spawn.X<x+w&&m.Spawn.Y>=y&&m.Spawn.Y<y+h)throw new ContentException("Prefab overlaps gameplay objects or spawn.");string id="building."+Guid.NewGuid().ToString("N")[..12];int z=m.Get(x,y).Z;m.Statics.RemoveAll(o=>o.X>=x&&o.X<x+w&&o.Y>=y&&o.Y<y+h);for(int yy=y;yy<y+h;yy++)for(int xx=x;xx<x+w;xx++){m.Get(xx,yy).Terrain="greyhaven.terrain.stone";m.Get(xx,yy).Z=z;if(yy==y||xx==x||yy==y+h-1&&xx!=x+w/2||xx==x+w-1){m.Statics.Add(new(){Id=id+"."+xx+"."+yy,Definition="greyhaven.static."+(yy==y||yy==y+h-1?"wall-left":"wall-right"),X=xx,Y=yy,Z=z});}}
 m.Objects.Add(new(){Id=id+".door",Kind="door",Name=type+" door",Visual="door",X=x+w/2,Y=y+h-1});m.Roofs.Add(new(){Id=id+".roof",Name=type=="inn"?"New Inn":"New Cottage",Kind="roof",X=x,Y=y,Width=w,Height=h});}
}
